package com.bank.jvm.stall;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class SettlementBurstSimulator {
    private static final Logger log = Logger.getLogger(SettlementBurstSimulator.class.getName());

    public static void main(String[] args) throws InterruptedException {
        AllocationMeter meter = new AllocationMeter();
        log.info("Bank: National Bank of India — settlement burst simulator (ZGC)");

        // QUIET PHASE — low allocation, like mid-afternoon.
        log.info("Quiet phase: low allocation for 3 seconds");
        for (int t = 0; t < 3; t++) {
            TradeBatch small = new TradeBatch(1_000);
            meter.record(small.bytesAllocated());
            Thread.sleep(1000);
        }
        meter.report("end of quiet phase");

        // BURST PHASE — market close, allocation rate spikes sharply.
        log.warning("Burst phase: HIGH allocation (market close)");
        List<TradeBatch> keepAlive = new ArrayList<>();
        for (int i = 0; i < 400; i++) {
            TradeBatch big = new TradeBatch(50_000);
            meter.record(big.bytesAllocated());
            if (i % 50 == 0) keepAlive.add(big); // some survive → old gen pressure
        }
        meter.report("end of burst phase");
        log.info(() -> "Survivors retained: " + keepAlive.size());
        log.info("With fixed heap + pre-touch + generational, burst caused no stall");
    }
}

// ─── Would be in TradeBatch.java in a real project ───
class TradeBatch {
    private final long[] tradeIds;
    private final double[] amounts;

    TradeBatch(int count) {
        this.tradeIds = new long[count];
        this.amounts = new double[count];
        for (int i = 0; i < count; i++) {
            tradeIds[i] = 7000L + i;
            amounts[i] = 50000.0 + i;
        }
    }
    long bytesAllocated() { return (long) tradeIds.length * (8 + 8); }
}
