package com.bank.jvm.stall;

import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Logger;

class AllocationMeter {
    private static final Logger log = Logger.getLogger(AllocationMeter.class.getName());
    private final AtomicLong totalBytes = new AtomicLong();
    private final long startNanos = System.nanoTime();

    void record(long bytes) { totalBytes.addAndGet(bytes); }

    void report(String phase) {
        long bytes = totalBytes.get();
        double seconds = (System.nanoTime() - startNanos) / 1_000_000_000.0;
        double mbPerSec = (bytes / (1024.0 * 1024.0)) / Math.max(seconds, 0.001);
        log.info(() -> String.format("Alloc [%s] total=%dMB avgRate=%.1f MB/s",
                phase, bytes / (1024 * 1024), mbPerSec));
    }
}
